CREATE OR REPLACE FUNCTION "publication"."reject_sealed_content_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  old_release_id uuid;
  new_release_id uuid;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    old_release_id := old.release_id;
    if exists (
      select 1 from publication.releases r
      where r.release_id = old_release_id and r.lifecycle_state = 'sealed'
    ) then
      raise exception 'sealed release % content is immutable', old_release_id using errcode = '55000';
    end if;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    new_release_id := new.release_id;
    if exists (
      select 1 from publication.releases r
      where r.release_id = new_release_id and r.lifecycle_state = 'sealed'
    ) then
      raise exception 'sealed release % content is immutable', new_release_id using errcode = '55000';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$$;

ALTER FUNCTION "publication"."reject_sealed_content_mutation"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "publication"."reject_sealed_release_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.lifecycle_state = 'sealed' then
    raise exception 'sealed release % is immutable', old.release_id using errcode = '55000';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$$;

ALTER FUNCTION "publication"."reject_sealed_release_mutation"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "review_moderation"."add_business_days"("start_at" timestamp with time zone, "business_days" integer) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  candidate timestamptz := start_at;
  remaining integer := business_days;
begin
  if business_days < 0 then
    raise exception 'business_days must not be negative' using errcode = '22023';
  end if;
  while remaining > 0 loop
    candidate := candidate + interval '1 day';
    if extract(isodow from candidate) between 1 and 5 then
      remaining := remaining - 1;
    end if;
  end loop;
  return candidate;
end;
$$;

ALTER FUNCTION "review_moderation"."add_business_days"("start_at" timestamp with time zone, "business_days" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "review_moderation"."enforce_decision_conflict"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  contributor_account_id uuid;
begin
  select submission.account_id into contributor_account_id
  from review_moderation.review_cases review_case
  join community_intake.submissions submission
    on submission.submission_id = review_case.submission_id
  where review_case.review_case_id = new.review_case_id;
  if contributor_account_id = new.decided_by_account_id then
    raise exception 'reviewer cannot decide their own submission' using errcode = '42501';
  end if;
  return new;
end;
$$;

ALTER FUNCTION "review_moderation"."enforce_decision_conflict"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "review_moderation"."enforce_review_case_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  contributor_account_id uuid;
begin
  if new.submission_id <> old.submission_id
    or new.opened_revision_number <> old.opened_revision_number
    or new.reopened_from_review_case_id is distinct from old.reopened_from_review_case_id then
    raise exception 'review case identity is immutable' using errcode = '55000';
  end if;
  if new.version <> old.version + 1 then
    raise exception 'review case version must increase by exactly one' using errcode = '40001';
  end if;
  if old.state = 'closed' then
    raise exception 'closed review cases are immutable; reopen creates a new record'
      using errcode = '55000';
  end if;
  if new.state <> old.state and not (
    (old.state = 'new' and new.state in ('assigned', 'closed'))
    or (old.state = 'assigned' and new.state = 'closed')
  ) then
    raise exception 'invalid review case state transition' using errcode = '23514';
  end if;
  if new.primary_assignee_id is not null then
    select account_id into contributor_account_id
    from community_intake.submissions
    where submission_id = new.submission_id;
    if contributor_account_id = new.primary_assignee_id then
      raise exception 'reviewer cannot be assigned to their own submission' using errcode = '42501';
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

ALTER FUNCTION "review_moderation"."enforce_review_case_transition"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "review_moderation"."reject_append_only_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  raise exception '% is append-only', tg_table_name using errcode = '55000';
end;
$$;

ALTER FUNCTION "review_moderation"."reject_append_only_mutation"() OWNER TO "postgres";

