CREATE TABLE IF NOT EXISTS "integration"."outbox_events" (
    "event_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "schema_version" smallint DEFAULT 1 NOT NULL,
    "event_type" "text" NOT NULL,
    "event_version" integer DEFAULT 1 NOT NULL,
    "source_context" "text" NOT NULL,
    "aggregate_type" "text" NOT NULL,
    "aggregate_id" "text" NOT NULL,
    "aggregate_version" bigint,
    "idempotency_key" "text" NOT NULL,
    "correlation_id" "uuid" NOT NULL,
    "causation_id" "uuid",
    "occurred_at" timestamp with time zone NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "payload" "jsonb" NOT NULL,
    "published_at" timestamp with time zone,
    "publish_attempts" integer DEFAULT 0 NOT NULL,
    "last_error_code" "text",
    "last_error_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "outbox_causation_not_self" CHECK ((("causation_id" IS NULL) OR ("causation_id" <> "event_id"))),
    CONSTRAINT "outbox_events_aggregate_id_check" CHECK ((("length"("aggregate_id") >= 1) AND ("length"("aggregate_id") <= 255))),
    CONSTRAINT "outbox_events_aggregate_type_check" CHECK (("aggregate_type" ~ '^[a-z][a-z0-9_.-]{1,63}$'::"text")),
    CONSTRAINT "outbox_events_aggregate_version_check" CHECK ((("aggregate_version" IS NULL) OR ("aggregate_version" >= 0))),
    CONSTRAINT "outbox_events_event_type_check" CHECK (("event_type" ~ '^[a-z][a-z0-9_.-]{2,127}$'::"text")),
    CONSTRAINT "outbox_events_event_version_check" CHECK (("event_version" > 0)),
    CONSTRAINT "outbox_events_idempotency_key_check" CHECK ((("length"("idempotency_key") >= 1) AND ("length"("idempotency_key") <= 255))),
    CONSTRAINT "outbox_events_payload_check" CHECK (("jsonb_typeof"("payload") = 'object'::"text")),
    CONSTRAINT "outbox_events_publish_attempts_check" CHECK (("publish_attempts" >= 0)),
    CONSTRAINT "outbox_events_schema_version_check" CHECK (("schema_version" = 1)),
    CONSTRAINT "outbox_events_source_context_check" CHECK (("source_context" ~ '^[a-z][a-z0-9_.-]{1,63}$'::"text")),
    CONSTRAINT "outbox_publication_state_consistent" CHECK ((("published_at" IS NULL) OR ("published_at" >= "occurred_at")))
);

ALTER TABLE "integration"."outbox_events" OWNER TO "postgres";

COMMENT ON TABLE "integration"."outbox_events" IS 'Authoritative transactional Outbox. Queue messages reference event_id; this table owns replay history.';

COMMENT ON COLUMN "integration"."outbox_events"."schema_version" IS 'Version of the shared envelope contract, not the domain event payload.';

COMMENT ON COLUMN "integration"."outbox_events"."event_version" IS 'Version of the named domain event payload.';

