    CONSTRAINT "derivatives_check" CHECK (("parent_asset_id" <> "derivative_asset_id")),
    CONSTRAINT "derivatives_derivative_kind_check" CHECK (("derivative_kind" = ANY (ARRAY['thumbnail'::"text", 'web'::"text", 'preview'::"text", 'crop'::"text", 'other'::"text"]))),
    CONSTRAINT "derivatives_transform_metadata_check" CHECK (("jsonb_typeof"("transform_metadata") = 'object'::"text"))
);

