    "display_order" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "panda_assets_display_order_check" CHECK (("display_order" >= 0)),
    CONSTRAINT "panda_assets_usage_role_check" CHECK (("usage_role" = ANY (ARRAY['cover'::"text", 'gallery'::"text", 'historical'::"text", 'evidence'::"text"])))
);

ALTER TABLE "media"."panda_assets" OWNER TO "postgres";

CREATE OR REPLACE VIEW "media"."pipeline_asset_export_v1" WITH ("security_barrier"='true') AS
 SELECT "a"."asset_id",
    "a"."source_id",
    "a"."storage_bucket",
    "a"."storage_key",
    "a"."content_sha256",
    "a"."media_type",
    "a"."byte_size",
    "a"."title",
    "a"."creator",
    "a"."copyright_text",
    "a"."license",
    "a"."attribution_text",
    "a"."rights_status",
    "a"."eligibility_status",
    "a"."taken_at",
    COALESCE("associations"."pandas", '[]'::"jsonb") AS "pandas",
    "a"."updated_at"
   FROM ("media"."assets" "a"
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('pandaId', "pa"."panda_id", 'usageRole', "pa"."usage_role", 'displayOrder', "pa"."display_order") ORDER BY "pa"."display_order", "pa"."panda_id", "pa"."usage_role") AS "pandas"
           FROM "media"."panda_assets" "pa"
          WHERE ("pa"."asset_id" = "a"."asset_id")) "associations" ON (true));

ALTER VIEW "media"."pipeline_asset_export_v1" OWNER TO "postgres";

COMMENT ON VIEW "media"."pipeline_asset_export_v1" IS 'Versioned Media-owned read contract for offline media processing and analysis.';

