CREATE OR REPLACE VIEW "panda"."pipeline_identity_export_v1" WITH ("security_barrier"='true') AS
 SELECT "p"."panda_id",
    "canonical"."slug" AS "canonical_slug",
    COALESCE("names"."names", '[]'::"jsonb") AS "names",
    COALESCE("external_ids"."external_identifiers", '[]'::"jsonb") AS "external_identifiers",
    "p"."updated_at"
   FROM ((("panda"."pandas" "p"
     LEFT JOIN LATERAL ( SELECT "s"."slug"
           FROM "panda"."slugs" "s"
          WHERE (("s"."panda_id" = "p"."panda_id") AND ("s"."slug_kind" = 'canonical'::"text") AND ("s"."valid_to" IS NULL))
          ORDER BY "s"."created_at" DESC, "s"."slug_id" DESC
         LIMIT 1) "canonical" ON (true))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('languageTag', "n"."language_tag", 'nameKind', "n"."name_kind", 'value', "n"."value", 'normalizedValue', "n"."normalized_value", 'isPrimary', "n"."is_primary") ORDER BY "n"."is_primary" DESC, "n"."language_tag", "n"."name_kind", "n"."value") AS "names"
           FROM "panda"."names" "n"
          WHERE (("n"."panda_id" = "p"."panda_id") AND ("n"."valid_to" IS NULL))) "names" ON (true))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('system', "e"."system", 'value', "e"."value", 'normalizedValue', "e"."normalized_value") ORDER BY "e"."system", "e"."normalized_value") AS "external_identifiers"
           FROM "panda"."external_identifiers" "e"
          WHERE ("e"."panda_id" = "p"."panda_id")) "external_ids" ON (true));

ALTER VIEW "panda"."pipeline_identity_export_v1" OWNER TO "postgres";

COMMENT ON VIEW "panda"."pipeline_identity_export_v1" IS 'Versioned Panda-owned read contract for offline identity-resolution/enrichment assistance.';

CREATE TABLE IF NOT EXISTS "pipeline"."artifacts" (
    "artifact_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "artifact_kind" "text" NOT NULL,
    "storage_bucket" "text" NOT NULL,
    "storage_key" "text" NOT NULL,
    "content_sha256" "text" NOT NULL,
    "byte_size" bigint NOT NULL,
    "media_type" "text" NOT NULL,
    "contract_schema_id" "text",
    "manifest" "jsonb" NOT NULL,
    "created_at" timestamp with time zone NOT NULL,
    CONSTRAINT "artifacts_artifact_kind_check" CHECK (("artifact_kind" ~ '^[a-z][a-z0-9_.-]{1,127}$'::"text")),
    CONSTRAINT "artifacts_byte_size_check" CHECK (("byte_size" >= 0)),
    CONSTRAINT "artifacts_check" CHECK ((POSITION(("content_sha256") IN ("storage_key")) > 0)),
    CONSTRAINT "artifacts_content_sha256_check" CHECK (("content_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "artifacts_manifest_check" CHECK (("jsonb_typeof"("manifest") = 'object'::"text")),
    CONSTRAINT "artifacts_media_type_check" CHECK ((("length"(TRIM(BOTH FROM "media_type")) >= 1) AND ("length"(TRIM(BOTH FROM "media_type")) <= 255))),
    CONSTRAINT "artifacts_storage_bucket_check" CHECK ((("length"(TRIM(BOTH FROM "storage_bucket")) >= 1) AND ("length"(TRIM(BOTH FROM "storage_bucket")) <= 255))),
