    CONSTRAINT "attempts_attempt_number_check" CHECK (("attempt_number" >= 1)),
    CONSTRAINT "attempts_check" CHECK ((("outcome" IS NULL) = ("completed_at" IS NULL))),
    CONSTRAINT "attempts_check1" CHECK ((("outcome" IS NULL) OR (("outcome" = 'completed'::"text") AND ("error_code" IS NULL) AND ("error_message" IS NULL)) OR (("outcome" = 'failed'::"text") AND ("error_code" IS NOT NULL) AND ("error_message" IS NOT NULL)))),
    CONSTRAINT "attempts_check2" CHECK ((("completed_at" IS NULL) OR ("completed_at" >= "started_at"))),
    CONSTRAINT "attempts_outcome_check" CHECK (("outcome" = ANY (ARRAY['completed'::"text", 'failed'::"text"]))),
    CONSTRAINT "attempts_worker_id_check" CHECK ((("length"(TRIM(BOTH FROM "worker_id")) >= 1) AND ("length"(TRIM(BOTH FROM "worker_id")) <= 200)))
);

