CREATE TABLE IF NOT EXISTS "pipeline"."jobs" (
    "job_id" "uuid" NOT NULL,
    "job_type" "text" NOT NULL,
    "contract_version" "text" DEFAULT 'panda-data.pipeline-job/v1'::"text" NOT NULL,
    "correlation_id" "uuid" NOT NULL,
    "state" "text" DEFAULT 'queued'::"text" NOT NULL,
    "parameters" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "input_artifacts" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "requested_at" timestamp with time zone NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "error_code" "text",
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "jobs_check" CHECK ((("state" = ANY (ARRAY['running'::"text", 'completed'::"text", 'failed'::"text"])) = ("started_at" IS NOT NULL))),
    CONSTRAINT "jobs_check1" CHECK ((("state" = ANY (ARRAY['completed'::"text", 'failed'::"text"])) = ("completed_at" IS NOT NULL))),
    CONSTRAINT "jobs_check2" CHECK (((("state" = 'failed'::"text") AND ("error_code" IS NOT NULL) AND ("error_message" IS NOT NULL)) OR (("state" <> 'failed'::"text") AND ("error_code" IS NULL) AND ("error_message" IS NULL)))),
    CONSTRAINT "jobs_check3" CHECK ((("started_at" IS NULL) OR ("started_at" >= "requested_at"))),
    CONSTRAINT "jobs_check4" CHECK ((("completed_at" IS NULL) OR (("started_at" IS NOT NULL) AND ("completed_at" >= "started_at")))),
    CONSTRAINT "jobs_contract_version_check" CHECK (("contract_version" = 'panda-data.pipeline-job/v1'::"text")),
    CONSTRAINT "jobs_input_artifacts_check" CHECK (("jsonb_typeof"("input_artifacts") = 'array'::"text")),
    CONSTRAINT "jobs_job_type_check" CHECK (("job_type" ~ '^[a-z][a-z0-9_.-]{1,127}$'::"text")),
    CONSTRAINT "jobs_parameters_check" CHECK (("jsonb_typeof"("parameters") = 'object'::"text")),
    CONSTRAINT "jobs_state_check" CHECK (("state" = ANY (ARRAY['queued'::"text", 'running'::"text", 'completed'::"text", 'failed'::"text"])))
);

