    CONSTRAINT "delivery_control_events_action_check" CHECK (("action" = ANY (ARRAY['apply'::"text", 'restore'::"text"]))),
    CONSTRAINT "delivery_control_events_check" CHECK (((("control_kind" = 'release_suspension'::"text") AND ("release_id" IS NOT NULL) AND ("resource_kind" IS NULL) AND ("resource_id" IS NULL)) OR (("control_kind" = 'resource_takedown'::"text") AND ("release_id" IS NULL) AND ("resource_kind" IS NOT NULL) AND ("resource_id" IS NOT NULL) AND ("length"(TRIM(BOTH FROM "resource_id")) > 0)))),
    CONSTRAINT "delivery_control_events_control_kind_check" CHECK (("control_kind" = ANY (ARRAY['release_suspension'::"text", 'resource_takedown'::"text"]))),
    CONSTRAINT "delivery_control_events_reason_check" CHECK ((("length"(TRIM(BOTH FROM "reason")) >= 3) AND ("length"(TRIM(BOTH FROM "reason")) <= 2000))),
    CONSTRAINT "delivery_control_events_resource_kind_check" CHECK ((("resource_kind" IS NULL) OR ("resource_kind" = ANY (ARRAY['panda'::"text", 'place'::"text", 'media'::"text", 'evidence'::"text"])))),
    CONSTRAINT "publication_delivery_control_actor_shape_check" CHECK (((("actor_account_id" IS NOT NULL) AND ("actor_system_key" IS NULL)) OR (("actor_account_id" IS NULL) AND ("actor_system_key" ~ '^[a-z][a-z0-9_.-]{2,63}$'::"text"))))
);

