COMMENT ON COLUMN "publication"."delivery_control_events"."actor_system_key" IS 'Code-controlled system actor for managed publication jobs; mutually exclusive with actor_account_id.';

CREATE TABLE IF NOT EXISTS "publication"."release_memberships" (
    "release_id" "uuid" NOT NULL,
    "resource_kind" "text" NOT NULL,
    "resource_id" "text" NOT NULL,
    "source_revision" "text" NOT NULL,
    "source_version" "text" NOT NULL,
    "source_sha256" "text" NOT NULL,
    "projection_sha256" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "release_memberships_projection_sha256_check" CHECK (("projection_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "release_memberships_resource_id_check" CHECK (("length"(TRIM(BOTH FROM "resource_id")) > 0)),
    CONSTRAINT "release_memberships_resource_kind_check" CHECK (("resource_kind" = ANY (ARRAY['panda'::"text", 'institution'::"text", 'place'::"text", 'lineage'::"text", 'residency'::"text", 'life_event'::"text", 'media'::"text", 'evidence'::"text"]))),
    CONSTRAINT "release_memberships_source_revision_check" CHECK (("length"(TRIM(BOTH FROM "source_revision")) > 0)),
    CONSTRAINT "release_memberships_source_sha256_check" CHECK (("source_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "release_memberships_source_version_check" CHECK (("length"(TRIM(BOTH FROM "source_version")) > 0))
);

ALTER TABLE "publication"."release_memberships" OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "publication"."release_transitions" (
    "transition_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "release_id" "uuid" NOT NULL,
    "transition_type" "text" NOT NULL,
    "from_release_id" "uuid",
    "actor_account_id" "uuid",
    "reason" "text" NOT NULL,
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actor_system_key" "text",
    CONSTRAINT "publication_release_transitions_actor_shape_check" CHECK (((("actor_account_id" IS NOT NULL) AND ("actor_system_key" IS NULL)) OR (("actor_account_id" IS NULL) AND ("actor_system_key" ~ '^[a-z][a-z0-9_.-]{2,63}$'::"text")))),
    CONSTRAINT "release_transitions_reason_check" CHECK ((("length"(TRIM(BOTH FROM "reason")) >= 3) AND ("length"(TRIM(BOTH FROM "reason")) <= 2000))),
    CONSTRAINT "release_transitions_transition_type_check" CHECK (("transition_type" = ANY (ARRAY['built'::"text", 'sealed'::"text", 'activated'::"text", 'rolled_back'::"text", 'suspended'::"text", 'restored'::"text"])))
);

ALTER TABLE "publication"."release_transitions" OWNER TO "postgres";

COMMENT ON COLUMN "publication"."release_transitions"."actor_system_key" IS 'Code-controlled system actor for managed publication jobs; mutually exclusive with actor_account_id.';

CREATE TABLE IF NOT EXISTS "publication"."releases" (
    "release_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "version" "text" NOT NULL,
    "projection_schema_version" integer DEFAULT 1 NOT NULL,
    "lifecycle_state" "text" DEFAULT 'building'::"text" NOT NULL,
    "created_by_account_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "built_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sealed_at" timestamp with time zone,
    "content_sha256" "text",
    "created_by_system_key" "text",
    CONSTRAINT "publication_releases_actor_shape_check" CHECK (((("created_by_account_id" IS NOT NULL) AND ("created_by_system_key" IS NULL)) OR (("created_by_account_id" IS NULL) AND ("created_by_system_key" ~ '^[a-z][a-z0-9_.-]{2,63}$'::"text")))),
    CONSTRAINT "releases_check" CHECK (((("lifecycle_state" = 'building'::"text") AND ("sealed_at" IS NULL) AND ("content_sha256" IS NULL)) OR (("lifecycle_state" = 'sealed'::"text") AND ("sealed_at" IS NOT NULL) AND ("content_sha256" IS NOT NULL)))),
    CONSTRAINT "releases_content_sha256_check" CHECK ((("content_sha256" IS NULL) OR ("content_sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "releases_lifecycle_state_check" CHECK (("lifecycle_state" = ANY (ARRAY['building'::"text", 'sealed'::"text"]))),
    CONSTRAINT "releases_projection_schema_version_check" CHECK (("projection_schema_version" >= 1)),
    CONSTRAINT "releases_version_check" CHECK ((("length"(TRIM(BOTH FROM "version")) >= 1) AND ("length"(TRIM(BOTH FROM "version")) <= 80)))
);

ALTER TABLE "publication"."releases" OWNER TO "postgres";

COMMENT ON COLUMN "publication"."releases"."created_by_system_key" IS 'Code-controlled system actor for managed publication jobs; mutually exclusive with created_by_account_id.';

CREATE TABLE IF NOT EXISTS "review_moderation"."decisions" (
    "decision_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "review_case_id" "uuid" NOT NULL,
    "active_revision_number" integer NOT NULL,
    "outcome" "review_moderation"."review_decision_outcome" NOT NULL,
    "user_visible_explanation" "text" NOT NULL,
    "internal_reason" "text",
    "selected_assertion_keys" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "duplicate_of_review_case_id" "uuid",
    "decided_by_account_id" "uuid" NOT NULL,
    "decided_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "decisions_active_revision_number_check" CHECK (("active_revision_number" >= 1)),
    CONSTRAINT "decisions_check" CHECK ((("outcome" <> 'accepted'::"review_moderation"."review_decision_outcome") OR ("jsonb_array_length"("selected_assertion_keys") > 0))),
    CONSTRAINT "decisions_check1" CHECK ((("outcome" <> 'duplicate'::"review_moderation"."review_decision_outcome") OR ("duplicate_of_review_case_id" IS NOT NULL))),
    CONSTRAINT "decisions_internal_reason_check" CHECK ((("internal_reason" IS NULL) OR (("length"(TRIM(BOTH FROM "internal_reason")) >= 3) AND ("length"(TRIM(BOTH FROM "internal_reason")) <= 4000)))),
    CONSTRAINT "decisions_selected_assertion_keys_check" CHECK (("jsonb_typeof"("selected_assertion_keys") = 'array'::"text")),
    CONSTRAINT "decisions_user_visible_explanation_check" CHECK ((("length"(TRIM(BOTH FROM "user_visible_explanation")) >= 10) AND ("length"(TRIM(BOTH FROM "user_visible_explanation")) <= 2000)))
);

ALTER TABLE "review_moderation"."decisions" OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "review_moderation"."review_cases" (
    "review_case_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "submission_id" "uuid" NOT NULL,
    "opened_revision_number" integer NOT NULL,
    "active_revision_number" integer NOT NULL,
    "state" "review_moderation"."review_case_state" DEFAULT 'new'::"review_moderation"."review_case_state" NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "primary_assignee_id" "uuid",
    "risk_level" "text" DEFAULT 'normal'::"text" NOT NULL,
    "duplicate_of_review_case_id" "uuid",
    "reopened_from_review_case_id" "uuid",
    "first_response_due_at" timestamp with time zone DEFAULT "review_moderation"."add_business_days"("now"(), 3) NOT NULL,
    "first_responded_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "review_cases_active_revision_number_check" CHECK (("active_revision_number" >= 1)),
    CONSTRAINT "review_cases_check" CHECK ((("state" = 'closed'::"review_moderation"."review_case_state") = ("closed_at" IS NOT NULL))),
    CONSTRAINT "review_cases_check1" CHECK ((("duplicate_of_review_case_id" IS NULL) OR ("duplicate_of_review_case_id" <> "review_case_id"))),
    CONSTRAINT "review_cases_check2" CHECK ((("reopened_from_review_case_id" IS NULL) OR ("reopened_from_review_case_id" <> "review_case_id"))),
    CONSTRAINT "review_cases_opened_revision_number_check" CHECK (("opened_revision_number" >= 1)),
    CONSTRAINT "review_cases_risk_level_check" CHECK (("risk_level" = ANY (ARRAY['normal'::"text", 'elevated'::"text", 'high'::"text"]))),
    CONSTRAINT "review_cases_version_check" CHECK (("version" >= 1))
);

ALTER TABLE "review_moderation"."review_cases" OWNER TO "postgres";

CREATE OR REPLACE VIEW "review_moderation"."review_case_queue" AS
 SELECT "review_case"."review_case_id",
    "review_case"."submission_id",
    "review_case"."opened_revision_number",
    "review_case"."active_revision_number",
    "review_case"."state",
    "review_case"."version",
    "review_case"."primary_assignee_id",
    "review_case"."risk_level",
    "review_case"."duplicate_of_review_case_id",
    "review_case"."reopened_from_review_case_id",
    "review_case"."first_response_due_at",
    "review_case"."first_responded_at",
    "review_case"."closed_at",
    "review_case"."created_at",
    "review_case"."updated_at",
    "submission"."target_type",
    "submission"."target_id",
    "submission"."contributor_status",
    (("review_case"."first_responded_at" IS NULL) AND ("review_case"."state" <> 'closed'::"review_moderation"."review_case_state") AND ("now"() > "review_case"."first_response_due_at")) AS "sla_overdue",
    GREATEST((0)::bigint, (EXTRACT(epoch FROM ("now"() - "review_case"."created_at")))::bigint) AS "queue_age_seconds"
   FROM ("review_moderation"."review_cases" "review_case"
     JOIN "community_intake"."submissions" "submission" ON (("submission"."submission_id" = "review_case"."submission_id")));

ALTER VIEW "review_moderation"."review_case_queue" OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "review_moderation"."source_verifications" (
    "source_verification_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "review_case_id" "uuid" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "active_revision_number" integer NOT NULL,
    "outcome" "review_moderation"."source_verification_outcome" NOT NULL,
    "normalized_locator" "text",
    "canonical_source_id" "text",
    "reason" "text" NOT NULL,
    "verified_by_account_id" "uuid" NOT NULL,
    "verified_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "source_verifications_active_revision_number_check" CHECK (("active_revision_number" >= 1)),
    CONSTRAINT "source_verifications_canonical_source_id_check" CHECK ((("canonical_source_id" IS NULL) OR (("length"(TRIM(BOTH FROM "canonical_source_id")) >= 1) AND ("length"(TRIM(BOTH FROM "canonical_source_id")) <= 255)))),
    CONSTRAINT "source_verifications_check" CHECK ((("outcome" <> 'verified'::"review_moderation"."source_verification_outcome") OR ("normalized_locator" IS NOT NULL))),
    CONSTRAINT "source_verifications_normalized_locator_check" CHECK ((("normalized_locator" IS NULL) OR (("length"(TRIM(BOTH FROM "normalized_locator")) >= 3) AND ("length"(TRIM(BOTH FROM "normalized_locator")) <= 2000)))),
    CONSTRAINT "source_verifications_reason_check" CHECK ((("length"(TRIM(BOTH FROM "reason")) >= 3) AND ("length"(TRIM(BOTH FROM "reason")) <= 2000)))
);

ALTER TABLE "review_moderation"."source_verifications" OWNER TO "postgres";

